import { Star } from "lucide-react"

export default function TestimonialSection() {
    const testimonios = [
        {
            nombre: "María Teresa, 52 años",
            antes: "Antes me sentía completamente invisible después de que mis hijos se fueron de casa. No sabía qué hacer con mi tiempo ni quién era yo sin ellos.",
            despues: "Después de las 8 semanas, redescubrí mi pasión por la escritura. Hoy tengo un blog y me despierto con una energía que no sentía a mis 30.",
            diferencia: "Isabel no te da consejos de libro, te acompaña con una calidez real."
        },
        {
            nombre: "Silvia, 48 años",
            antes: "Vivía en piloto automático, en un trabajo que me apagaba y creyendo que ya era muy tarde para volver a empezar mi carrera.",
            despues: "Tomé la decisión de emprender. Estructuramos un plan realista que me quitó el miedo. Hoy vivo de mi propio negocio.",
            diferencia: "Me hizo ver que la experiencia de mis años es mi mayor ventaja, no un lastre."
        }
    ]

    return (
        <section className="w-full bg-brand-crema py-24 px-6 lg:px-8">
            <div className="max-w-6xl mx-auto">
                <h2 className="text-3xl md:text-5xl font-bold font-sans text-brand-text mb-16 text-center">
                    Historias de mujeres que ya vibran con propósito
                </h2>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-10 lg:gap-14">
                    {testimonios.map((t, idx) => (
                        <div key={idx} className="bg-white rounded-2xl p-8 md:p-10 shadow-sm border border-brand-beige relative">
                            <div className="flex gap-1 mb-6 text-brand-olive-light">
                                {[1, 2, 3, 4, 5].map((s) => <Star key={s} className="w-5 h-5 fill-current" />)}
                            </div>

                            <div className="space-y-4 mb-8">
                                <div>
                                    <h4 className="text-sm font-bold text-brand-brown-light uppercase tracking-wider mb-1">Antes de empezar</h4>
                                    <p className="text-brand-text-muted italic">&quot;{t.antes}&quot;</p>
                                </div>
                                <div>
                                    <h4 className="text-sm font-bold text-brand-olive uppercase tracking-wider mb-1">Hoy</h4>
                                    <p className="text-brand-text font-medium text-lg leading-relaxed">&quot;{t.despues}&quot;</p>
                                </div>
                            </div>

                            <div className="mt-8 pt-6 border-t border-brand-beige flex items-center justify-between">
                                <div>
                                    <div className="font-bold text-brand-text font-sans">{t.nombre}</div>
                                    <div className="text-sm text-brand-text-muted mt-1 max-w-[250px] italic">
                                        &quot;{t.diferencia}&quot;
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    )
}
