import { BookOpen } from "lucide-react"

export default function CourseCurriculum() {
    const modulos = [
        {
            titulo: "Sesión 1: El Diagnóstico del Alma",
            desc: "Reconectar con tu esencia más allá de las etiquetas (madre, esposa, profesional)."
        },
        {
            titulo: "Sesión 2 y 3: Desmontando Creencias",
            desc: "Adiós al 'es demasiado tarde' y al miedo a la invisibilidad en esta nueva etapa."
        },
        {
            titulo: "Sesión 4 y 5: El Mapa de tu Propósito",
            desc: "Descubrir qué te hace vibrar hoy, alineando tus valores con tus deseos actuales."
        },
        {
            titulo: "Sesión 6 y 7: Plan de Acción Realista",
            desc: "Cómo llevar ese propósito a tu día a día con pasos concretos y medibles."
        },
        {
            titulo: "Sesión 8: Vuelo Sostenido",
            desc: "Herramientas emocionales para mantener este bienestar a largo plazo."
        }
    ]

    return (
        <section id="programa" className="w-full bg-white py-20 px-6 lg:px-8 border-y border-brand-beige/50">
            <div className="max-w-5xl mx-auto">
                <div className="text-center mb-16">
                    <h2 className="text-3xl md:text-5xl font-bold font-sans text-brand-text mb-4">
                        Te presento <span className="text-brand-olive px-2 text-nowrap">Reinventadas 5.0</span>
                    </h2>
                    <p className="text-xl md:text-2xl text-brand-text-muted font-outfit max-w-3xl mx-auto">
                        Un proceso estructurado, profundo y a tu propio ritmo. <br className="hidden md:block" />
                        8 sesiones de alto impacto, herramientas exclusivas y mi acompañamiento personal.
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {modulos.map((modulo, idx) => (
                        <div
                            key={idx}
                            className="bg-brand-crema rounded-xl p-8 border border-brand-beige shadow-sm flex flex-col items-start transition-colors hover:bg-brand-beige/30"
                        >
                            <div className="bg-[#f0ece1] text-brand-brown-dark rounded-full p-3 mb-6 inline-block">
                                <BookOpen className="w-6 h-6" />
                            </div>
                            <h3 className="text-xl font-bold text-brand-text mb-3">{modulo.titulo}</h3>
                            <p className="text-brand-text-muted leading-relaxed font-outfit">{modulo.desc}</p>
                        </div>
                    ))}

                    {/* Card Bono */}
                    <div className="bg-brand-olive text-white rounded-xl p-8 shadow-md flex flex-col items-start">
                        <h3 className="text-xl font-bold mb-3 flex items-center gap-2">
                            🎁 Bonus Exclusivos
                        </h3>
                        <ul className="space-y-3 font-outfit text-white/90">
                            <li className="flex items-start gap-2">
                                <span>•</span> Material de ejercicios descargable en cada sesión.
                            </li>
                            <li className="flex items-start gap-2">
                                <span>•</span> Acceso ilimitado al contenido de por vida en la plataforma.
                            </li>
                            <li className="flex items-start gap-2">
                                <span>•</span> Soporte vía WhatsApp para dudas durante el proceso.
                            </li>
                        </ul>
                    </div>
                </div>
            </div>
        </section>
    )
}
