export default function ProblemSection() {
    const dolores = [
        "¿Sentís que dedicaste tu vida a cuidar de otros y ahora apenas reconocés qué es lo que te apasiona a vos?",
        "¿Te aterra pensar que \"ya es tarde\" para hacer ese gran cambio que sentís en el pecho?",
        "¿Transitas tus días en piloto automático, sintiendo una desconexión profunda entre quién sos y lo que hacés?",
        "¿Notas el paso del tiempo y sentís que te estás volviendo invisible en una etapa donde tendrías que estar floreciendo?"
    ];

    return (
        <section id="problema" className="w-full bg-white py-20 px-6 lg:px-8">
            <div className="max-w-4xl mx-auto flex flex-col items-center">
                <h2 className="text-3xl md:text-5xl font-bold font-sans text-brand-text mb-12 text-center w-full max-w-2xl leading-snug">
                    ¿Te sentís identificada con alguna de estas situaciones?
                </h2>

                <div className="flex flex-col gap-6 w-full max-w-3xl">
                    {dolores.map((dolor, index) => (
                        <div
                            key={index}
                            className="flex items-start bg-brand-beige/50 p-6 rounded-xl border border-brand-crema shadow-sm"
                        >
                            <div className="shrink-0 bg-brand-olive text-white rounded-full w-8 h-8 flex items-center justify-center font-bold mr-4 mt-1">
                                ?
                            </div>
                            <p className="text-lg md:text-xl text-brand-text-muted leading-relaxed font-outfit">
                                {dolor}
                            </p>
                        </div>
                    ))}
                </div>

                <div className="mt-16 text-center max-w-3xl">
                    <p className="text-2xl font-medium text-brand-brown-dark leading-relaxed">
                        Te entiendo perfectamente. No sos la única y, lo más importante: <strong className="text-brand-text font-bold">esta etapa no es una crisis, es tu mayor oportunidad de reinvención.</strong>
                    </p>
                </div>
            </div>
        </section>
    )
}
