import { Button } from "@/components/ui/button"
import Image from "next/image"

export default function HeroSection() {
    return (
        <section className="relative w-full bg-[#fdfaf6] min-h-screen py-12 px-6 lg:px-12 overflow-hidden overflow-x-hidden flex items-center">
            
            {/* Header / Navbar Integrado */}
            <div className="absolute top-0 left-0 w-full flex justify-between items-center py-6 px-8 md:px-16 z-50">
                <div className="text-2xl font-sans text-brand-text">
                    Reinventadas <span className="text-[#c16447] italic font-serif">5.0</span>
                </div>
                <div className="hidden md:flex items-center gap-8 font-outfit text-sm font-semibold tracking-wide text-brand-text">
                    <a href="#programa" className="hover:text-brand-brown transition-colors uppercase">El Programa</a>
                    <a href="#sobre-mi" className="hover:text-brand-brown transition-colors uppercase">Sobre Mí</a>
                    <a href="#testimonios" className="hover:text-brand-brown transition-colors uppercase">Testimonios</a>
                </div>
                <Button className="bg-[#1c1c1c] text-white hover:bg-black rounded-full px-6 py-5 font-outfit text-sm">
                    Reservar mi lugar
                </Button>
            </div>

            <div className="max-w-7xl mx-auto w-full relative z-10 flex flex-col lg:flex-row items-center justify-between gap-12 mt-20">
                
                {/* Columna Izquierda: Textos */}
                <div className="w-full lg:w-1/2 flex flex-col items-start text-left z-20">
                    <span className="border border-brand-brown/30 text-brand-brown font-semibold tracking-widest uppercase text-xs px-4 py-1.5 rounded-full mb-8 inline-block shadow-sm bg-white/50">
                        MIDLIFE COACHING
                    </span>

                    <h1 className="text-5xl md:text-7xl font-sans text-brand-text leading-[1.1] mb-6">
                        Es tu tiempo <br/>para <span className="font-serif italic text-[#c16447]">vibrar</span>.
                    </h1>

                    <p className="text-lg md:text-xl text-brand-text-muted mb-10 max-w-lg font-outfit leading-relaxed">
                        Reinventá tu vida a los 50 con propósito y autenticidad. Caminar hacia tu propósito es una decisión, no una edad.
                    </p>

                    <div className="flex flex-col sm:flex-row gap-4 w-full justify-start">
                        <Button asChild className="bg-[#c16447] hover:bg-[#a6533a] text-white font-semibold text-sm px-8 py-6 h-auto rounded-full shadow-md transition-all uppercase tracking-wide">
                            <a href="#programa">→ QUIERO EL PROGRAMA</a>
                        </Button>
                        <Button variant="outline" asChild className="bg-white border-brand-brown/20 text-brand-text-muted font-semibold text-sm px-8 py-6 h-auto rounded-full hover:bg-brand-crema transition-all uppercase tracking-wide">
                            <a href="#contacto">VER QUÉ INCLUYE</a>
                        </Button>
                    </div>
                </div>

                {/* Columna Derecha: Imagen y Burbujas */}
                <div className="w-full lg:w-1/2 relative mt-16 lg:mt-0 flex justify-center">
                    
                    <div className="relative w-[340px] h-[480px] md:w-[420px] md:h-[580px] mx-auto z-10">
                        
                        {/* Blob Background / Decoration */}
                        <div className="absolute inset-0 bg-[#e8e4d3] rounded-t-[200px] rounded-b-[200px] transform rotate-3 -z-10 shadow-xl"></div>
                        <div className="absolute inset-x-8 bottom-0 h-[80%] bg-white rounded-t-[150px] rounded-b-[40px] -z-5 shadow-2xl"></div>

                        {/* Imagen Principal */}
                        <div className="absolute inset-0 bottom-8 overflow-hidden rounded-t-[200px] rounded-b-[40px] z-10 flex items-end">
                            <Image 
                                src="/images/isabel-hero.png" 
                                alt="Isabel Martinez Campos" 
                                fill
                                className="object-cover object-center"
                                priority
                            />
                        </div>

                        {/* Burbujas Flotantes (Speech Bubbles) */}
                        {/* 1. Eres más poderosa (Arriba Izquierda) */}
                        <div className="absolute -left-16 md:-left-24 top-12 z-20 bg-[#4d5343] text-white text-sm md:text-base font-serif italic px-5 py-3 rounded-tr-2xl rounded-tl-2xl rounded-bl-2xl rounded-br-sm shadow-xl max-w-[200px]">
                            "Eres más poderosa de lo que crees."
                        </div>

                        {/* 2. Nunca es tarde (Arriba Derecha) */}
                        <div className="absolute -right-12 md:-right-20 top-24 z-20 bg-[#c16447] text-white text-sm md:text-base font-serif italic px-5 py-3 rounded-tr-2xl rounded-tl-2xl rounded-bl-sm rounded-br-2xl shadow-xl max-w-[180px]">
                            "Nunca es tarde para empezar."
                        </div>

                        {/* 3. Tu tiempo es ahora (Medio Izquierda) */}
                        <div className="absolute -left-20 md:-left-28 top-[45%] z-20 bg-[#7a8165] text-white text-sm md:text-base font-serif italic px-5 py-3 rounded-t-2xl rounded-br-2xl rounded-bl-sm shadow-xl max-w-[190px]">
                            "Tu tiempo es ahora, no después."
                        </div>

                        {/* 4. Cada día es nueva oport. (Medio Derecha) */}
                        <div className="absolute -right-16 md:-right-24 top-[55%] z-20 bg-[#f4ebd9] text-[#7a8165] text-sm md:text-base font-serif italic px-5 py-3 rounded-t-2xl rounded-bl-2xl rounded-br-sm shadow-xl max-w-[200px]">
                            "Cada día es una nueva oportunidad."
                        </div>

                        {/* 5. Reinventarse amor propio (Abajo Izquierda) */}
                        <div className="absolute -left-12 md:-left-20 bottom-24 z-20 bg-[#fdfaf6] text-[#7a8165] text-sm md:text-base font-serif italic px-5 py-3 rounded-tr-2xl rounded-tl-2xl rounded-bl-2xl rounded-br-sm shadow-xl border border-[#e8e4d3] max-w-[200px]">
                            "Reinventarse es un acto de amor propio."
                        </div>

                        {/* 6. Vibrar es derecho (Abajo Derecha) */}
                        <div className="absolute -right-8 md:-right-16 bottom-16 z-20 bg-[#a6533a] text-white text-sm md:text-base font-serif italic px-5 py-3 rounded-tr-2xl rounded-tl-sm rounded-b-2xl shadow-xl max-w-[190px]">
                            "Vibrar es tu derecho, no un lujo."
                        </div>

                    </div>
                </div>

            </div>
        </section>
    )
}




