import { Check } from "lucide-react"

export default function SolutionSection() {
    const soluciones = [
        "Despertar cada mañana con claridad absoluta sobre lo que querés y los pasos precisos para lograrlo.",
        "Tomar decisiones alineadas con tu esencia, sin la pesada mochila de la culpa o el \"deber ser\".",
        "Sentirte vibrante, segura de tu propio cuerpo y de tu edad, sabiendo que tenés el poder de dirigir tu futuro.",
        "Navegar los cambios de la mediana edad (nido vacío, menopausia, roles) no como pérdidas, sino como la liberación de tu verdadero yo."
    ]

    return (
        <section id="solucion" className="w-full bg-[var(--color-brand-beige)] py-20 px-6 lg:px-8 relative">
            {/* Patrón orgánico opcional superior */}
            <div className="absolute top-0 left-0 w-full overflow-hidden flex transform -translate-y-1/2">
                <svg className="w-full text-white fill-current h-[60px]" viewBox="0 0 1440 60" preserveAspectRatio="none">
                    <path d="M0,30 C320,60 420,-30 720,30 C1020,90 1120,-10 1440,30 L1440,60 L0,60 Z"></path>
                </svg>
            </div>

            <div className="max-w-4xl mx-auto flex flex-col items-center z-10 relative">
                <h2 className="text-3xl md:text-5xl font-bold font-sans text-brand-text mb-12 text-center w-full max-w-2xl leading-snug">
                    Imaginá por un momento sentirte así...
                </h2>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-4xl mt-4">
                    {soluciones.map((solucion, index) => (
                        <div
                            key={index}
                            className="flex items-start bg-white p-8 rounded-2xl shadow-sm hover:shadow-md transition-shadow duration-300 border border-brand-crema/50"
                        >
                            <div className="shrink-0 bg-brand-olive text-white rounded-full p-2 mr-4 flex items-center justify-center">
                                <Check className="w-5 h-5" />
                            </div>
                            <p className="text-lg text-brand-text leading-relaxed font-outfit mt-1">
                                {solucion}
                            </p>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    )
}
